contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We take lockTime and amount as inputs and send amount wei to c in the Put call.
    function run(uint lockTime, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        // read before-values via public getter
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this)); if (__ESBMC_reverted()) return;

        bool reverted;
        // perform the state-changing call as a top-level statement
        c.Put{value: amount}(lockTime); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // read after-values
        (uint afterUnlock, uint afterBal) = c.Acc(address(this)); if (__ESBMC_reverted()) return;

        // General rule:
        // - If Put reverted then unlockTime must not have increased (afterUnlock >= beforeUnlock is allowed but we require afterUnlock <= beforeUnlock to assert no increase).
        // - If Put succeeded then afterUnlock >= beforeUnlock and afterUnlock <= block.timestamp + lockTime.
        // Note: block.timestamp is observable inside the same transaction only via the implied semantics; we conservatively express upper bound relative to current block.timestamp.
        assert(
            (reverted && afterUnlock <= beforeUnlock)
            ||
            (!reverted && afterUnlock >= beforeUnlock && afterUnlock <= block.timestamp + lockTime)
        );
    }

    // allow receiving Ether refunds if any
    receive() external payable {}
}

